mapper.select:
SELECT u.*
FROM user u
JOIN follow f ON f.followee_id = u.id
WHERE follower_id = #{userId}
ORDER BY created_at DESC;

SELECT u.*
FROM user u
JOIN follow f ON f.follower_id = u.id
WHERE followee_id = #{userId}
ORDER BY created_at DESC;

SELECT EXISTS(
    SELECT 1
    FROM follow
    WHERE follower_id = #{followerId}
        AND followee_id = #{followeeId}
)

mapper.update:
UPDATE follow
SET notified = #{notified},
    updated_at = NOW()
WHERE follower_id = #{followerId}
    AND followee_id = #{followeeId}
    AND notified != #{notified}

mapper.delete:
DELETE
FROM follow
WHERE follower_id = #{followerId}
    AND followee_id = #{followeeId}
